def choose_move(observation):
    mode = observation.get('mode', None)
    grid = observation.get('grid', [])
    my_pos = observation.get('position', (0, 0))
    opponents = observation.get('opponents', [])
    resources = observation.get('resources', [])
    territory_map = observation.get('territory', [])
    width = observation.get('width', 0)
    height = observation.get('height', 0)

    x, y = my_pos

    def is_valid(pos):
        nx, ny = pos
        if 0 <= nx < width and 0 <= ny < height:
            if grid and grid[ny][nx] == 0:
                return True
        return False

    target_pos = None
    if mode == 'resource_collection' and resources:
        target_pos = min(resources, key=lambda r: abs(r[0]-x)+abs(r[1]-y))
    elif mode == 'pursuit_evasion' and opponents:
        target_pos = min(opponents, key=lambda o: abs(o[0]-x)+abs(o[1]-y))
    elif mode == 'territory_control' and territory_map:
        if territory_map:
            target_pos = territory_map[0]
    else:
        target_pos = None

    dx, dy = 0, 0
    if target_pos:
        tx, ty = target_pos
        delta_x = tx - x
        delta_y = ty - y
        if abs(delta_x) > abs(delta_y):
            dx = 1 if delta_x > 0 else -1 if delta_x < 0 else 0
        elif abs(delta_y) > 0:
            dy = 1 if delta_y > 0 else -1 if delta_y < 0 else 0
        new_pos = (x + dx, y + dy)
        if not is_valid(new_pos):
            for alt_dx, alt_dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                test_pos = (x + alt_dx, y + alt_dy)
                if is_valid(test_pos):
                    dx, dy = alt_dx, alt_dy
                    break
    else:
        dx, dy = 0, 0

    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]
